(function(r,f){const m=f();if(typeof module==='object')module.exports=m;else r.Model=m})(globalThis,()=>{const labels={camera:'Use your camera',microphone:'Use your microphone',notifications:'Show notifications',controller:'Read controller input',storage:'Use site storage'};function validate(x,now=Date.now()){if(!x||!Object.hasOwn(labels,x.kind)||typeof x.id!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(x.id)||!Number.isSafeInteger(x.navigationEpoch)||x.navigationEpoch<0||typeof x.supported!=='boolean'||!Number.isSafeInteger(x.expiresAt)||x.expiresAt<=now||x.expiresAt>now+120000)throw Error('Expired or invalid request');const u=new URL(x.origin);if(u.protocol!=='https:'||u.origin!==x.origin||x.origin.length>300)throw Error('Secure origin required');return {...x}}function answer(x,decision,now){x=validate(x,now);if(!['allow-once','deny'].includes(decision)||decision==='allow-once'&&!x.supported)throw Error('Permission unavailable');return{requestId:x.id,navigationEpoch:x.navigationEpoch,decision}}return{labels,validate,answer}});
